tool_input.command:
cat > tax-rates.json <<'EOF'
{
  "CA": 0.0725,
  "NY": 0.04,
  "TX": 0.0625
}
EOF
cat > src/tax.js <<'EOF'
import { percentOf } from "./money.js";
import salesTaxRates from "../tax-rates.json" with { type: "json" };

/** The tax rate for a region, zero when the region is untaxed. */
export function taxRate(region) {
  return salesTaxRates[region] ?? 0;
}

/** Tax on an amount for a region, rounded to the cent. */
export function taxFor(amount, region) {
  return percentOf(amount, taxRate(region));
}
EOF
cat > test/tax.test.js <<'EOF'
import { test } from "node:test";
import assert from "node:assert/strict";
import { taxFor, taxRate } from "../src/tax.js";
import { percentOf } from "../src/money.js";
import salesTaxRates from "../tax-rates.json" with { type: "json" };

// Expectations read tax-rates.json so finance can change a rate without breaking tests.
test("listed regions have the rate in tax-rates.json", () => {
  assert.equal(taxRate("CA"), salesTaxRates.CA);
  assert.equal(taxRate("NY"), salesTaxRates.NY);
});

test("unlisted regions are untaxed", () => {
  assert.equal(taxRate("OR"), 0);
  assert.equal(taxFor(10000, "OR"), 0);
});

test("tax rounds to the nearest cent", () => {
  assert.equal(taxFor(2300, "CA"), percentOf(2300, salesTaxRates.CA));
  assert.equal(taxFor(2300, "TX"), percentOf(2300, salesTaxRates.TX));
});
EOF
sed -i 's|^- `src/tax.js`: tax rates by region.|- `src/tax.js`: tax by region, using the rates in `tax-rates.json` (finance edits that file and redeploys).|' README.md
npm run coverage 2>&1 | grep -E "tax|^ℹ (pass|fail)|# (pass|fail)"; git status --short
